/* Round 32 (EMP tool): the M24 orbits of all 2^24 seed patterns of 24 cells.
 *
 * Exact integer arithmetic only (bit masks); no floating point, no randomness, no hashing.
 * The group is generated by the two automorphisms gM0, gM1 of the GLM Golay code
 * (MathieuOrbitsData.lean; found by m24_search.py).  Every 24-bit pattern is labelled with
 * its orbit by breadth-first search over the two generators.  For each number of marked cells
 * ("defects") it prints the orbit sizes and the smallest pattern of each orbit as a
 * representative.  Smallest orbits = largest stabilisers = the most symmetric arrangements;
 * with |M24| = 244823040 (classical) the stabiliser order is 244823040 / (orbit size).
 *
 * Expected: 49 orbits in total (the classical count for M24 on F_2^24).
 * The Lean file MathieuOrbitsData.lean certifies the orbits for up to 7 cells, the octads and
 * the dodecads; the rest of this census is EMP.
 *
 * Build and run:  gcc -O2 m24_orbit_census.c -o m24_orbit_census && ./m24_orbit_census
 * Memory: about 130 MB.  Time: a few seconds.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

static const int g0[24] = {1, 2, 3, 4, 5, 0, 8, 22, 23, 10, 12, 6, 21, 19, 13, 20, 14, 18, 16, 17, 9, 15, 11, 7};
static const int g1[24] = {23, 22, 21, 20, 19, 0, 2, 7, 3, 10, 13, 16, 18, 5, 9, 4, 15, 11, 17, 6, 12, 8, 1, 14};

static uint32_t apply(const int *g, uint32_t x) {
  uint32_t y = 0;
  for (int i = 0; i < 24; i++)
    if (x >> i & 1) y |= 1u << g[i];
  return y;
}

int main(void) {
  int *label = calloc((size_t)1 << 24, sizeof(int));
  uint32_t *queue = malloc(sizeof(uint32_t) << 24);
  if (!label || !queue) { fprintf(stderr, "out of memory\n"); return 1; }
  int norb = 0;
  long size[25][16];
  uint32_t rep[25][16];
  int nk[25] = {0};
  for (uint32_t s = 0; s < (1u << 24); s++) {
    if (label[s]) continue;
    norb++;
    int k = __builtin_popcount(s);
    long head = 0, tail = 0;
    queue[tail++] = s;
    label[s] = norb;
    while (head < tail) {
      uint32_t y = queue[head++];
      uint32_t z = apply(g0, y);
      if (!label[z]) { label[z] = norb; queue[tail++] = z; }
      z = apply(g1, y);
      if (!label[z]) { label[z] = norb; queue[tail++] = z; }
    }
    rep[k][nk[k]] = s;
    size[k][nk[k]++] = tail;
  }
  printf("M24 orbits on the 2^24 patterns of 24 cells: %d\n", norb);
  printf("cells  orbits  sizes (smallest representative; stabiliser order = 244823040/size)\n");
  for (int k = 0; k <= 24; k++) {
    printf("%5d  %6d ", k, nk[k]);
    for (int i = 0; i < nk[k]; i++)
      printf(" %ld(rep %u; stab %ld)", size[k][i], rep[k][i], 244823040L / size[k][i]);
    printf("\n");
  }
  free(label);
  free(queue);
  return 0;
}
